{

"kind": "propose",
"summary": "The container's CPU limit is too low, causing consistent throttling and delays. Increasing the CPU limit to 300m will alleviate this.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "CPU limit of 200m is insufficient for the app's demand, causing 90% throttling and delays.",
    "supporting": ["ev-container_cpu", "ev-container_logs_tail"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "cpu": "300m"
        }
      }
    }
  },
  "expected_effect": "Raise the CPU limit to 300m, reducing throttling and resolving delays.",
  "rationale": "Logs show consistent CPU backlogs aligning with 90% throttling at 200m limit. Raising the limit to 300m provides buffer without affecting memory.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-container_logs_tail"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit"]
}
}
